//! **A null in the identity column is refused by name** (`identity-scan-refuses-a-null-by-name`,
//! its form's §4): the refusal says the column is null in so many rows, and says nothing of a shared
//! identity unless non-null values repeat. A file with no null keeps its outcome and its details.
//!
//! Every file is generated by `spatial_engine::fixture`, written and then opened, never a
//! hand-built schema. These tests read no scan counter, so they may share one process.

use std::path::PathBuf;

use spatial_engine::fixture::{
    write_geoparquet, FixtureSpec, IdentityMode, NarrowColumn, NullBearingValues, NullBearingWidth,
};
use spatial_engine::identity::{IdUniqueness, IdentityDeclaration};
use spatial_engine::{CancelToken, Dataset, EngineError};

const WIDTHS: [NullBearingWidth; 8] = [
    NullBearingWidth::Int8,
    NullBearingWidth::Int16,
    NullBearingWidth::Int32,
    NullBearingWidth::Int64,
    NullBearingWidth::UInt8,
    NullBearingWidth::UInt16,
    NullBearingWidth::UInt32,
    NullBearingWidth::UInt64,
];

fn write(name: &str, features: usize, identity: IdentityMode) -> PathBuf {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../target/fixtures/identity-null");
    std::fs::create_dir_all(&dir).expect("fixture dir");
    let path = dir.join(format!("{name}.parquet"));
    let spec = FixtureSpec {
        features,
        avg_vertices: 8,
        identity,
        ..Default::default()
    };
    write_geoparquet(&path, &spec).expect("write fixture");
    path
}

fn null_bearing(
    name: &str,
    width: NullBearingWidth,
    column: NarrowColumn,
    values: NullBearingValues,
) -> PathBuf {
    let mode = IdentityMode::NullBearing {
        width,
        column,
        values,
    };
    write(&format!("{name}-{width:?}"), 100, mode)
}

/// The refusal's `column`, `detail` and `identity_source`, or a panic naming what came instead.
fn refused(result: Result<Dataset, EngineError>) -> (String, String, String) {
    match result {
        Err(EngineError::IdentityUnusable {
            column,
            detail,
            identity_source,
            ..
        }) => (column, detail, identity_source),
        Ok(_) => panic!("expected IdentityUnusable, got an open"),
        Err(other) => panic!("expected IdentityUnusable, got {other:?}"),
    }
}

/// W-1 of the form's §2.4, rendered.
fn w1(nulls: u64, rows: u64) -> String {
    format!(
        "the column is null in {nulls} of {rows} rows, so not every feature carries an identity"
    )
}

/// W-2 of the form's §2.4, rendered: W-1, then the second clause.
fn w2(nulls: u64, rows: u64, present: u64, distinct: u64) -> String {
    let w1 = w1(nulls, rows);
    format!("{w1}; the other {present} rows carry only {distinct} distinct values, so at least two of those features share an identity")
}

/// **T1.** F-1 and F-7: one null among otherwise unique values, and every row null, are refused
/// as a null with W-1, and the detail names no shared identity. The refusal's source is the file's
/// own `id`.
///
/// Mutation M-1: the null check removed. Observed at commit 69e363251158: this test fails at its `detail` assertion,
/// the refusal reading the repeat detail.
#[test]
fn a_single_null_in_an_otherwise_unique_integer_id_is_refused_by_name_as_a_null() {
    let cases = [
        (NullBearingValues::OneNull, 1),
        (NullBearingValues::AllNull, 100),
    ];
    for (values, nulls) in cases {
        let path = null_bearing("t1", NullBearingWidth::UInt64, NarrowColumn::Id, values);
        let (column, detail, source) = refused(Dataset::open(&path));
        assert_eq!(column, "id");
        assert_eq!(detail, w1(nulls, 100), "{values:?}");
        assert!(!detail.contains("share an identity"), "{detail}");
        assert_eq!(source, "file:id");
    }
}

/// **T2.** F-2: a null beside repeated non-null values is one refusal naming both facts.
///
/// Mutation M-2: the null refusal always gives W-1. Observed at commit 69e363251158: this test fails at its
/// `detail` assertion, the refusal naming the null alone.
#[test]
fn a_null_beside_repeated_values_is_refused_naming_both() {
    let path = null_bearing(
        "t2",
        NullBearingWidth::UInt64,
        NarrowColumn::Id,
        NullBearingValues::OneNullAndARepeat,
    );
    let (column, detail, _) = refused(Dataset::open(&path));
    assert_eq!(column, "id");
    assert_eq!(detail, w2(1, 100, 99, 98));
}

/// **T3.** F-3 and F-3d: a single null is refused as W-1 in each of the eight widths, native
/// (`id`) and declared (`parcel_key`, whose refusal says `mapped:parcel_key`).
///
/// Mutation M-3: the null check runs only for `Int64` and `UInt64`. Observed at commit 69e363251158: this test
/// fails at the native `detail` assertion for `Int8`.
/// Mutation M-9: the null site values `identity_source` as `IdSource::File` does, whatever the
/// declaration. Observed at commit 69e363251158: this test fails at the F-3d `mapped:parcel_key` assertion for `Int8`.
#[test]
fn a_null_is_refused_by_name_in_every_integer_width_admission_takes() {
    let one = NullBearingValues::OneNull;
    for width in WIDTHS {
        let path = null_bearing("t3", width, NarrowColumn::Id, one);
        let (column, detail, _) = refused(Dataset::open(&path));
        assert_eq!(column, "id", "{width:?}");
        assert_eq!(detail, w1(1, 100), "{width:?}");
    }
    for width in WIDTHS {
        let path = null_bearing("t3d", width, NarrowColumn::ParcelKey, one);
        let declaration = IdentityDeclaration::new("parcel_key", "test", "2026-11-27T00:00:00Z");
        let opened = Dataset::open_with_declared_identity(&path, declaration, &CancelToken::new());
        let (column, detail, source) = refused(opened);
        assert_eq!(column, "parcel_key", "{width:?}");
        assert_eq!(detail, w1(1, 100), "{width:?}");
        assert_eq!(source, "mapped:parcel_key", "{width:?}");
    }
}

/// **T4.** F-4: a nullable column holding no null is admitted in each width, verified over its
/// 100 rows: the refusal is decided by the null count and never by the field's nullability.
///
/// Mutation M-4: refusal on `field.is_nullable()` in place of the count. Observed at commit 69e363251158: this test
/// fails at the open of the first width, which is refused.
#[test]
fn a_nullable_integer_id_holding_no_null_is_still_admitted_in_every_width() {
    for width in WIDTHS {
        let path = null_bearing("t4", width, NarrowColumn::Id, NullBearingValues::NoNull);
        let dataset = Dataset::open(&path).unwrap_or_else(|e| panic!("{width:?}: {e:?}"));
        let identity = dataset.identity();
        assert_eq!(identity.uniqueness(), IdUniqueness::VerifiedAtOpenFullFile);
        assert_eq!(identity.verified_rows(), Some(100), "{width:?}");
        assert_eq!(identity.max_value(), Some(99), "{width:?}");
    }
}

/// **T5.** F-5: with no null, the repeated-values detail is today's, byte for byte (2,000 rows,
/// one distinct value).
///
/// Mutation M-5: `nulls` computed as `rows - distinct`. Observed at commit 69e363251158: this test fails at its
/// `detail` assertion, the repeat refusal reading as a null.
#[test]
fn the_repeated_values_refusal_is_unchanged_when_no_value_is_null() {
    let path = write("t5", 2_000, IdentityMode::DuplicateIds);
    let (column, detail, _) = refused(Dataset::open(&path));
    assert_eq!(column, "id");
    assert_eq!(
        detail,
        "2000 rows carry only 1 distinct values, so at least two features share an identity. \
         ADR-010 rule 2 resolves a pick through this id, and a shared id returns a \
         wrong-but-plausible feature with nothing raised"
    );
}

/// **T6.** F-6: a null beside a negative value keeps the negative refusal, which runs first.
///
/// Mutation M-6: the null check placed before the negative check. Observed at commit 69e363251158: this test fails at
/// its `negative value (-1)` assertion.
#[test]
fn a_null_beside_a_negative_value_keeps_the_negative_refusal() {
    let path = null_bearing(
        "t6",
        NullBearingWidth::Int32,
        NarrowColumn::Id,
        NullBearingValues::OneNullAndANegative,
    );
    let (column, detail, _) = refused(Dataset::open(&path));
    assert_eq!(column, "id");
    assert!(detail.contains("negative value (-1)"), "{detail}");
}
